<script setup lang="ts">
// Author by Lab | zefry
import {ref} from 'vue';import {locale} from '../i18n';import WorkspaceIcon from './WorkspaceIcon.vue';
type Shift={shift_id:string;outlet_id:string;device_id:string;opened_at:number;sales_count:number;review_digest:string;cash:Record<string,any>};
const props=defineProps<{shifts:Shift[];businessId?:string;version?:number;busy:boolean;reason:string}>();const emit=defineEmits<{command:[body:Record<string,unknown>];reason:[value:string]}>();
const chosen=ref<Shift|null>(null),confirmation=ref(''),reconciled=ref(false),reviewed=ref(false);const tr=(id:string,en:string)=>locale.value==='id'?id:en;
function select(s:Shift){chosen.value=s;confirmation.value='';reconciled.value=false;reviewed.value=false;}
function recover(){const s=chosen.value;if(!s||confirmation.value!==s.shift_id||!reconciled.value||!reviewed.value||props.reason.trim().length<12)return;emit('command',{action:props.businessId?'shift.recover':'shift.recover_initial',...(props.businessId?{id:props.businessId}:{}),version:props.version??0,reason:props.reason,shift_id:s.shift_id,review_digest:s.review_digest,reviewed:true,offline_reconciled:true});}
</script>
<template><section class="recovery-panel"><div class="recovery-title"><span><WorkspaceIcon name="refresh-cw" :size="24"/></span><div><p>INCIDENT RECOVERY</p><h3>{{tr('Pemulihan shift bermasalah','Recover a blocked shift')}}</h3></div></div><p class="recovery-copy">{{tr('Pemulihan melepas slot kasir agar shift baru dapat dibuka. Transaksi dan bukti kas tetap tersimpan; shift ditandai perlu rekonsiliasi, bukan dianggap tutup kas yang sah.','Recovery releases the register for a new shift. Sales and cash evidence remain preserved; the shift requires reconciliation and is not treated as an approved financial close.')}}</p><div v-if="!shifts.length" class="recovery-empty"><WorkspaceIcon name="circle-check"/> {{tr('Tidak ada shift aktif yang perlu dipulihkan.','No active shifts to recover.')}}</div><div v-for="s in shifts" :key="s.shift_id" class="recovery-row"><div><strong>{{s.outlet_id}}</strong><small>{{s.device_id}} · {{new Date(s.opened_at*1000).toLocaleString()}}</small><code>{{s.shift_id}}</code><small>{{s.sales_count}} {{tr('transaksi tersimpan','persisted sales')}}</small></div><button type="button" :disabled="busy" @click="select(s)">{{tr('Tinjau pemulihan','Review recovery')}}</button></div><form v-if="chosen" class="recovery-review" @submit.prevent="recover"><h4>{{tr('Konfirmasi pemulihan','Confirm recovery')}}</h4><p>{{tr('Hentikan transaksi di perangkat terkait. Sinkronkan atau ekspor dan amankan seluruh antrean offline terlebih dahulu. Sesi dicabut dan lease lama dinonaktifkan; transaksi offline lama perlu penanganan operator agar tidak hilang atau tercatat ganda.','Stop transactions on this register. Sync or export and secure its offline queue first. Sessions are revoked and old leases disabled; old offline transactions need operator reconciliation to avoid loss or duplication.')}}</p><label>{{tr('Alasan insiden · minimal 12 karakter','Incident reason · at least 12 characters')}}<input :value="reason" @input="emit('reason',($event.target as HTMLInputElement).value)" required minlength="12" maxlength="300"/></label><label>{{tr('Ketik ID shift untuk konfirmasi','Type the shift ID to confirm')}}<code>{{chosen.shift_id}}</code><input v-model="confirmation" required autocomplete="off"/></label><label class="recovery-check"><input v-model="reconciled" type="checkbox" required/>{{tr('Perangkat telah dihentikan dan antrean offline telah diamankan serta ditinjau.','The register is stopped and its offline queue secured and reviewed.')}}</label><label class="recovery-check"><input v-model="reviewed" type="checkbox" required/>{{tr('Saya memahami pemulihan ini tidak mengesahkan uang kas atau menghapus transaksi.','I understand recovery neither approves cash nor deletes transactions.')}}</label><div class="recovery-actions"><button type="button" :disabled="busy" @click="chosen=null">{{tr('Batal','Cancel')}}</button><button class="recovery-submit" :disabled="busy||!reviewed||!reconciled||confirmation!==chosen.shift_id||reason.trim().length<12">{{tr('Pulihkan slot shift','Recover shift slot')}}</button></div></form></section></template>
<style scoped>
.recovery-panel{border:1px solid #e4d5ba;border-radius:14px;background:#fffcf6;padding:24px;margin:20px 0}.recovery-title{display:flex;align-items:center;gap:14px}.recovery-title>span{display:grid;place-items:center;width:48px;height:48px;border-radius:12px;color:#996522;background:#f9edda}.recovery-title p{font-size:10px;letter-spacing:1.5px;color:#976b30;margin:0 0 5px}.recovery-title h3{font-size:18px;margin:0;color:#473a28}.recovery-copy,.recovery-review p{font-size:13px;line-height:1.8;color:#70634f}.recovery-empty{display:flex;align-items:center;gap:10px;padding:18px;color:#477161;background:#f1f7f2;border-radius:10px;font-size:13px}.recovery-row{display:flex;align-items:center;justify-content:space-between;gap:20px;border-top:1px solid #eadfce;padding:18px 0}.recovery-row small,.recovery-row code{display:block;font-size:11px;margin-top:5px;overflow-wrap:anywhere}.recovery-panel button{border:1px solid #c9b799;background:#fff;color:#665038;border-radius:8px;padding:10px 16px;cursor:pointer;font-size:12px;font-weight:650}.recovery-panel button:disabled{opacity:.5;cursor:not-allowed}.recovery-panel button:focus-visible{outline:3px solid #a17435;outline-offset:3px}.recovery-review{background:#fff;border:1px solid #e4d5ba;border-radius:12px;padding:20px;margin-top:15px}.recovery-review label{display:flex;flex-direction:column;gap:8px;font-size:12px;margin:18px 0;color:#544735}.recovery-review input:not([type=checkbox]){width:100%;border:1px solid #d8cbb7;border-radius:8px;padding:11px;background:#fff;color:#273647}.recovery-review .recovery-check{flex-direction:row;align-items:flex-start;line-height:1.7}.recovery-check input{width:17px;height:17px;flex-shrink:0}.recovery-actions{display:flex;justify-content:flex-end;gap:10px}.recovery-actions .recovery-submit{background:#8d4e27;color:#fff;border-color:#8d4e27}@media(max-width:600px){.recovery-panel{padding:16px}.recovery-row{align-items:flex-start;flex-direction:column}.recovery-review{padding:14px}}
</style>
